PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime);
CREATE TABLE IF NOT EXISTS "shops" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "slug" varchar not null, "description" text, "logo_url" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "status" varchar not null default 'active', foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "category_id" integer not null, "name" varchar not null, "slug" varchar not null, "description" text, "price" numeric not null, "stock" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "low_stock_threshold" integer not null default '5', foreign key("shop_id") references "shops"("id") on delete cascade, foreign key("category_id") references "categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "carts" ("id" integer primary key autoincrement not null, "created_at" datetime, "updated_at" datetime, "user_id" integer not null, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "cart_items" ("id" integer primary key autoincrement not null, "cart_id" integer not null, "product_id" integer not null, "quantity" integer not null, "price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references products("id") on delete cascade on update no action, foreign key("cart_id") references carts("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "user_id" integer not null, "shop_id" integer not null, "total" numeric not null, "status" varchar not null default 'pending', "shipping_address" text not null, "billing_address" text, "payment_method" varchar not null, "payment_status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer not null, "quantity" integer not null, "price" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "order_id" integer not null, "transaction_id" varchar not null, "amount" numeric not null, "currency" varchar not null default 'XOF', "status" varchar not null default 'pending', "payment_method" varchar not null, "payment_details" text, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "product_images" ("id" integer primary key autoincrement not null, "product_id" integer not null, "image_url" varchar not null, "is_primary" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notifications" ("id" integer primary key autoincrement not null, "user_id" integer not null, "title" varchar not null, "message" text not null, "type" varchar not null default 'info', "link" varchar, "is_read" tinyint(1) not null default '0', "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notification_subscriptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar not null, "target" varchar not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "plans" ("id" integer primary key autoincrement not null, "name" varchar not null, "display_name" varchar not null, "price" numeric not null default '0', "prices" text, "currency" varchar not null default 'FCFA', "features" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "subscriptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "plan_id" integer not null, "start_date" datetime not null, "end_date" datetime not null, "status" varchar not null default 'active', "trial_ends_at" datetime, "payment_method" varchar, "transaction_id" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("plan_id") references "plans"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "phone" varchar not null, "role" varchar not null default ('customer'), "avatar_url" varchar, "bio" text, "is_active" tinyint(1) not null default ('1'), "last_login_at" datetime, "deleted_at" datetime, "referral_code" varchar, "referred_by" integer, "two_factor_secret" varchar, "two_factor_confirmed_at" datetime, foreign key("referred_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "referrals" ("id" integer primary key autoincrement not null, "referrer_id" integer not null, "referred_id" integer not null, "code" varchar not null, "commission" numeric not null default '0', "status" varchar not null default 'pending', "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("referrer_id") references "users"("id") on delete cascade, foreign key("referred_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "promo_codes" ("id" integer primary key autoincrement not null, "code" varchar not null, "target_plan" varchar not null, "discount_amount" numeric not null, "duration" integer, "usage_limit" integer, "used_count" integer not null default '0', "expires_at" datetime, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "promo_code_usages" ("id" integer primary key autoincrement not null, "promo_code_id" integer not null, "user_id" integer not null, "subscription_id" integer, "used_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("promo_code_id") references "promo_codes"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("subscription_id") references "subscriptions"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "delivery_zones" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "name" varchar not null, "description" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "delivery_cities" ("id" integer primary key autoincrement not null, "delivery_zone_id" integer not null, "name" varchar not null, "region" varchar, "created_at" datetime, "updated_at" datetime, foreign key("delivery_zone_id") references "delivery_zones"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "delivery_fees" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "zone" varchar, "amount" numeric not null default '0', "free_threshold" numeric, "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "statistics" ("id" integer primary key autoincrement not null, "shop_id" integer, "event_type" varchar not null, "session_id" varchar, "ip_address" varchar, "user_agent" varchar, "referrer" varchar, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "accounting" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "type" varchar not null, "category" varchar not null, "amount" numeric not null, "description" varchar, "reference" varchar, "transaction_date" date not null, "status" varchar not null default 'pending', "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "domains" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "domain" varchar not null, "status" varchar not null default 'pending', "is_primary" tinyint(1) not null default '0', "verified_at" datetime, "dns_records" text, "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "backups" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null default 'full', "status" varchar not null default 'pending', "file_path" varchar, "file_size" integer, "metadata" text, "started_at" datetime, "completed_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "tickets" ("id" integer primary key autoincrement not null, "user_id" integer not null, "shop_id" integer, "title" varchar not null, "description" text not null, "category" varchar not null default 'general', "priority" varchar not null default 'medium', "status" varchar not null default 'open', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("shop_id") references "shops"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "ticket_replies" ("id" integer primary key autoincrement not null, "ticket_id" integer not null, "user_id" integer not null, "message" text not null, "is_admin" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "entity" varchar not null, "entity_id" integer, "description" text, "old_values" text, "new_values" text, "ip_address" varchar, "user_agent" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "webhooks" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "url" varchar not null, "secret" varchar, "events" text not null, "is_active" tinyint(1) not null default '1', "retry_count" integer not null default '3', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "reviews" ("id" integer primary key autoincrement not null, "product_id" integer not null, "user_id" integer not null, "rating" integer not null, "comment" text, "images" text, "is_verified" tinyint(1) not null default '0', "likes" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "display_name" varchar not null, "description" varchar, "is_default" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "display_name" varchar not null, "group" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "role_permission" ("id" integer primary key autoincrement not null, "role_id" integer not null, "permission_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("role_id") references "roles"("id") on delete cascade, foreign key("permission_id") references "permissions"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "user_role" ("id" integer primary key autoincrement not null, "user_id" integer not null, "role_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "coupons" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "code" varchar not null, "type" varchar not null, "value" numeric not null, "min_order_amount" numeric, "usage_limit" integer, "used_count" integer not null default '0', "valid_from" datetime, "valid_until" datetime, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "loyalty_settings" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "points_per_1000" integer not null default '10', "points_to_cash_rate" numeric not null default '1', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "loyalty_points" ("id" integer primary key autoincrement not null, "user_id" integer not null, "shop_id" integer not null, "points" integer not null, "type" varchar not null, "reference" varchar, "description" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("shop_id") references "shops"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "conversations" ("id" integer primary key autoincrement not null, "shop_id" integer not null, "customer_id" integer not null, "order_id" integer, "status" varchar not null default 'active', "last_message_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("shop_id") references "shops"("id") on delete cascade, foreign key("customer_id") references "users"("id") on delete cascade, foreign key("order_id") references "orders"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "messages" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "sender_id" integer not null, "message" text not null, "type" varchar not null default 'text', "is_read" tinyint(1) not null default '0', "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "conversations"("id") on delete cascade, foreign key("sender_id") references "users"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "categories_slug_unique" on "categories" ("slug");
CREATE UNIQUE INDEX "shops_slug_unique" on "shops" ("slug");
CREATE UNIQUE INDEX "products_slug_unique" on "products" ("slug");
CREATE UNIQUE INDEX "payments_transaction_id_unique" on "payments" ("transaction_id");
CREATE INDEX "products_name_index" on "products" ("name");
CREATE INDEX "products_category_id_index" on "products" ("category_id");
CREATE INDEX "products_shop_id_index" on "products" ("shop_id");
CREATE INDEX "products_price_index" on "products" ("price");
CREATE INDEX "products_created_at_index" on "products" ("created_at");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_referral_code_unique" on "users" ("referral_code");
CREATE UNIQUE INDEX "promo_codes_code_unique" on "promo_codes" ("code");
CREATE UNIQUE INDEX "domains_domain_unique" on "domains" ("domain");
CREATE UNIQUE INDEX "roles_name_unique" on "roles" ("name");
CREATE UNIQUE INDEX "permissions_name_unique" on "permissions" ("name");
CREATE UNIQUE INDEX "coupons_code_unique" on "coupons" ("code");
COMMIT;
